/**
 * Archives several issues in one call. Ids that name no issue of this org, or
 * an already-archived one, are reported in `skipped` and left untouched; every
 * other issue must pass the single-archive `issue:archive` check, and one
 * denial rejects the whole call before anything is written or published.
 */
export async function bulkArchiveIssues(
  actor: Actor,
  input: BulkArchiveIssuesInput,
): Promise<{ archived: readonly IssueId[]; skipped: readonly IssueId[] }> {
  assertOrgScope(actor, input.orgId);

  const requestedIds = [...new Set(input.issueIds)];
  const found = new Map(
    (await issueRepo.findIssuesByIds(input.orgId, requestedIds)).map(
      (issue) => [issue.id, issue] as const,
    ),
  );

  const candidates: Issue[] = [];
  const skipped: IssueId[] = [];
  for (const issueId of requestedIds) {
    const issue = found.get(issueId);
    if (issue === undefined || isArchived(issue)) {
      skipped.push(issueId);
    } else {
      candidates.push(issue);
    }
  }

  for (const issue of candidates) {
    assertCan(actor, "issue:archive", issueResource(issue));
  }

  const archivedRows: Issue[] = [];
  for (const issue of candidates) {
    archivedRows.push(await issueRepo.archiveIssue(input.orgId, issue.id));
  }

  for (const archived of archivedRows) {
    await emit("issue.archived", {
      ...actorEnvelope(actor),
      issueId: archived.id,
      projectId: archived.projectId,
    });
  }

  return { archived: archivedRows.map((issue) => issue.id), skipped };
}

